\usepackage{pgfplots}
\usepgfplotslibrary{colormaps}
\pgfplotsset{compat=1.18}

\begin{document}
\begin{tikzpicture}
\begin{axis}[
    view={60}{30},
    xlabel={$x$},
    ylabel={$y$},
    zlabel={$z$},
    title={Hyperboloid of Two Sheets},
    width=12cm,
    height=10cm,
    axis lines=center,
    enlargelimits=0.15,
    grid=major,
    samples=25,
    domain=-3:3,
    y domain=-3:3,
    colormap/viridis,
]
% Upper sheet
\addplot3[surf, opacity=0.7, mesh/rows=15] 
    ({x}, {2*sqrt(1 + x^2/4 + y^2)}, {y});
% Lower sheet
\addplot3[surf, opacity=0.7, mesh/rows=15] 
    ({x}, {-2*sqrt(1 + x^2/4 + y^2)}, {y});
\end{axis}
\end{tikzpicture}
